const SEED_FILES = ['ใบเสนอราคา.pdf', 'สลิปโอนเงิน.jpg', 'ใบเสร็จ.pdf', 'รูปงานบูธ.jpg', 'รายงานยอดขาย.xlsx', 'เอกสารคืนของ.pdf', 'รายงานคืนสินค้า.xlsx', 'ภาพถ่ายงาน.jpg'];
const fileIcon = (name) => {
  const ext = (name.split('.').pop() || '').toLowerCase();
  if (['jpg','jpeg','png','gif','webp'].includes(ext)) return { icon: 'image', color: 'oklch(60% 0.16 25)' };
  if (['pdf'].includes(ext)) return { icon: 'file', color: 'oklch(55% 0.18 25)' };
  if (['xlsx','xls','csv'].includes(ext)) return { icon: 'file', color: 'oklch(55% 0.16 150)' };
  if (['doc','docx'].includes(ext)) return { icon: 'file', color: 'oklch(55% 0.16 240)' };
  return { icon: 'file', color: 'var(--ink-3)' };
};
const fmtFileSize = (b) => b < 1024 ? `${b} B` : b < 1024*1024 ? `${(b/1024).toFixed(1)} KB` : `${(b/1024/1024).toFixed(1)} MB`;

const AttachmentManager = ({ req, state, setState, currentUser }) => {
  // Seed initial files from req.attachments count if not present
  const initial = React.useMemo(() => {
    if (req.attachedFiles) return req.attachedFiles;
    const n = req.attachments || 0;
    return Array.from({ length: n }).map((_, i) => ({
      id: `${req.id}-f${i}`, name: SEED_FILES[i % SEED_FILES.length],
      size: 50000 + Math.floor(Math.random() * 0) + (i * 100000),
      uploadedBy: req.requester, uploadedAt: req.createdAt
    }));
  }, [req.id, req.attachedFiles, req.attachments, req.requester, req.createdAt]);

  const [dragOver, setDragOver] = React.useState(false);
  const inputRef = React.useRef(null);

  const updateFiles = (newFiles) => {
    setState({
      requests: state.requests.map(r => r.id === req.id ? { ...r, attachedFiles: newFiles, attachments: newFiles.length } : r),
      activities: [{ at: nowTh(), user: currentUser.id, action: 'import', refId: req.id, summary: `อัปโหลดไฟล์ ${newFiles.length - initial.length > 0 ? `${newFiles.length - initial.length} ไฟล์` : ''}` }, ...state.activities]
    });
  };

  const addFiles = (fileList) => {
    if (!fileList || fileList.length === 0) return;
    const newOnes = Array.from(fileList).map((f, i) => ({
      id: `${req.id}-f-${Date.now()}-${i}`,
      name: f.name, size: f.size,
      uploadedBy: currentUser.id, uploadedAt: nowTh()
    }));
    const next = [...initial, ...newOnes];
    setState({
      requests: state.requests.map(r => r.id === req.id ? { ...r, attachedFiles: next, attachments: next.length } : r),
      activities: [{ at: nowTh(), user: currentUser.id, action: 'import', refId: req.id, summary: `อัปโหลด ${newOnes.length} ไฟล์` }, ...state.activities]
    });
    window.toast(`อัปโหลด ${newOnes.length} ไฟล์เรียบร้อย`, { level: 'success' });
  };

  const removeFile = (id) => {
    const next = initial.filter(f => f.id !== id);
    setState({
      requests: state.requests.map(r => r.id === req.id ? { ...r, attachedFiles: next, attachments: next.length } : r)
    });
    window.toast('ลบไฟล์แล้ว', { level: 'info' });
  };

  const onDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    addFiles(e.dataTransfer?.files);
  };

  return (
    <>
      <h3 className="card-title mt-24 mb-12 spread"><span><Icon name="paperclip" size={14} /> เอกสารแนบ ({initial.length})</span></h3>
      <div onDragOver={(e) => { e.preventDefault(); setDragOver(true); }} onDragLeave={() => setDragOver(false)} onDrop={onDrop}
        style={{
          border: `2px dashed ${dragOver ? 'var(--brand)' : 'var(--border)'}`,
          background: dragOver ? 'var(--brand-soft)' : 'transparent',
          borderRadius: 10, padding: 14, transition: 'all 0.15s', marginBottom: 12
        }}>
        <input ref={inputRef} type="file" multiple style={{ display: 'none' }} onChange={(e) => { addFiles(e.target.files); e.target.value = ''; }} />
        <div className="row gap-12" style={{ alignItems: 'center', justifyContent: 'center', padding: 8 }}>
          <Icon name="upload" size={18} style={{ color: 'var(--brand-ink)' }} />
          <div>
            <div className="text-sm medium">ลากไฟล์มาวางที่นี่ หรือ <button className="btn btn-ghost btn-sm" style={{ height: 24, padding: '2px 8px', color: 'var(--brand-ink)' }} onClick={() => inputRef.current?.click()}>เลือกไฟล์</button></div>
            <div className="text-xs muted mt-2">รองรับ PDF, รูปภาพ, Excel, Word — ขนาดไม่เกิน 10MB</div>
          </div>
        </div>
      </div>
      {initial.length === 0 ? <div className="text-xs muted center" style={{ padding: 16 }}>ยังไม่มีเอกสารแนบ</div> : (
        <div className="grid grid-3">
          {initial.map(f => {
            const ic = fileIcon(f.name);
            const u = state.users[f.uploadedBy];
            return (
              <div key={f.id} className="row gap-10" style={{ padding: 10, border: '1px solid var(--border)', borderRadius: 8, background: 'var(--surface-2)', position: 'relative' }}>
                <div style={{ width: 36, height: 36, background: 'var(--brand-soft)', color: ic.color, borderRadius: 6, display: 'grid', placeItems: 'center', flexShrink: 0 }}><Icon name={ic.icon} size={16} /></div>
                <div style={{ minWidth: 0, flex: 1 }}>
                  <div className="text-sm medium" style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={f.name}>{f.name}</div>
                  <div className="text-xs muted">{fmtFileSize(f.size)} · {u?.name?.split(' ')[0] || 'ระบบ'}</div>
                </div>
                <button className="btn btn-ghost btn-sm btn-icon-only" onClick={() => removeFile(f.id)} title="ลบ" style={{ width: 24, height: 24 }}><Icon name="x" size={11} /></button>
              </div>
            );
          })}
        </div>
      )}
    </>
  );
};

