              const replySummary = replyTo !== null ? `ตอบกลับความคิดเห็น #${replyTo + 1}` : (mentions.length > 0 ? `เพิ่มความคิดเห็น · แท็ก ${mentions.map(id => state.users[id]?.name?.split(' ')[0] || id).join(', ')}` : 'เพิ่มความคิดเห็น');
              const acts = [{ at: nowTh(), user: currentUser.id, action: 'comment', refId: req.id, summary: replySummary }];
